// Synthetic response fixtures exercise contracts/UI, not model recommendation quality.
import {candidate,activity,final} from './home-solution-conversation.mjs';
export const productQuestion='A client wants a new digital product in six months. Should we recruit more engineers if our managers are already stretched?';
export const turnoverQuestion='I want to reduce turnover';
const spec={
 product:[
  ['Protect a delivery team','Deliver a narrowed product pilot with a protected decision owner before committing to additional hires.','Product sponsor','Before staffing approval, agree the client acceptance slice and delegate delivery decisions.','Delivery lead','After scope agreement, run a pilot delivery cycle with the protected team.','A tested product slice and a visible management workload; six-month delivery is not verified.','Review accepted features, blocked decisions and manager workload at each delivery checkpoint.'],
  ['Buy a bounded workstream','Deliver a separable product workstream through a partner with an internal acceptance owner.','Product owner','Before vendor commitment, define a separable work package and acceptance checks.','Vendor delivery lead','After commercial and integration review, deliver the work package for internal acceptance.','An accepted work package; vendor capacity, cost and integration effort remain unknown.','Review acceptance failures, handoff delays and internal oversight effort at delivery checkpoints.'],
  ['Hire after capacity review','Fill an evidenced engineering gap after protecting management capacity and checking the hiring timetable.','Engineering lead','Before opening roles, identify the uncovered skills and a manager with onboarding capacity.','Talent acquisition lead','After funding and delivery gates are met, recruit for the evidenced gap and review onboarding.','Capacity matched to the verified gap; the hire count and arrival date remain unknown.','Track onboarding load and delivery capacity against the reviewed gap before expanding recruitment.'],
 ],
 turnover:[
  ['Reduce avoidable workload','Pilot a workload and prioritisation change while monitoring employee feedback and delivery.','Operations lead','Before the pilot, agree which low-value work to pause and collect a workload baseline.','Team manager','After agreement, run the revised work allocation and review staff feedback.','A tested workload change; any effect on turnover is unproven.','Review workload feedback and delivery measures, then matched-period turnover with its denominator.'],
  ['Open internal pathways','Pilot a transparent internal opportunity process with protected exploration time.','Talent mobility lead','Before launch, identify available opportunities and agree manager release conditions.','Career development lead','After release review, run the pathway pilot and collect participation feedback.','A tested access route to opportunities; mobility availability and retention effects are unknown.','Review opportunity access and participant feedback before comparing matched-period retention.'],
  ['Improve manager check-ins','Pilot regular manager check-ins that turn employee concerns into tracked actions.','People partner','Before the pilot, agree a concise check-in format and escalation owner.','Team manager','After workload review, run check-ins and close agreed actions with employees.','A tested support routine; survey associations do not prove causes or retention gains.','Review action completion and support feedback, keeping survey coverage separate from turnover rates.'],
 ],
};
export function actionPlans(kind,body){return spec[kind].map(([name,objective,owner,step,nextOwner,nextStep,result,measure],index)=>{
 const c=candidate(kind+'-'+(index+1));
 return {...c,goal:{statement:kind==='product'?'Deliver the client digital product within the requested six-month horizon':'Reduce turnover',turnId:body.message.id},name,objective,approach:'Agree the decision gate, run the proposed delivery activity, then review what happened.',rationale:result,tradeoffs:[kind==='product'?'Protected management time is still required; staffing and funding are unverified.':'This is a proposed mechanism, not a demonstrated cause or quantified retention effect.'],nextStep:step+' Suggested owner: '+owner+'.',successMeasure:measure,activities:[{...activity('c1',name+' preparation'),domain:'execution',ownerRole:owner,step},{...activity('c2',name+' pilot'),domain:kind==='product'?'execution':'manager_workload',ownerRole:nextOwner,step:nextStep,dependsOn:['c1']}],quantities:[]};
});}
export const batch=plans=>({name:'evaluate_action_plans',args:{candidates:plans,constraintUpdates:[]}});
export function actionPlanAnswer(kind,plans){return `I recommend ${plans[0].name} as a provisional first move: ${kind==='product'?'protect management capacity before adding an onboarding burden.':'test a practical workload change; the available associations do not establish why people leave.'}\n\n`+plans.map((plan,index)=>`Proposed Action Plan ${index+1}: ${plan.name}. ${plan.objective} ${plan.nextStep} ${plan.rationale} Success measure: ${plan.successMeasure}`).join('\n\n')+'\n\nTell me which plan to refine or combine. We can optionally focus on a team next. Nothing has been saved.';}
export function recommendationSteps(kind,body){const plans=actionPlans(kind,body);return [batch(plans),final(actionPlanAnswer(kind,plans),plans.map(plan=>plan.id))];}
export function combinedPlan(body){
 const [left,right]=[...new Map(body.state.working.map(item=>[item.id,item])).values()];
 return {...left.candidate,id:'combined-approach',base:{kind:'working',id:left.id,revision:left.revision},name:'Combined delivery pilot',objective:'Run the selected pilot activities together after reviewing their dependencies and shared resources.',rationale:'Combine the chosen mechanisms without assuming shared participants, cash savings or better outcomes.',activities:[left,right].map((source,index)=>({...source.candidate.activities[1],id:'c'+(index+1),mode:'retain',source:{kind:'working',id:source.id,revision:source.revision,activityId:'c2'},dependsOn:[],audienceOf:null})),quantities:[]};
}
